// CORE Living Earth — plain-language problem view. Pure functions: record in, escaped HTML out (testable).
// The problem registry (data/problems/registry.json, generated by scripts/problems.mjs) is written in French. V9 shows
// it in the selected language through ptext(): a fixed dictionary for the registry's controlled vocabulary and
// templates for its generated sentences (numbers are taken from the record). An unknown sentence is shown in French
// with a visible “(original in French)” mark — never silently.
import { icon } from '../ui/icons.mjs';
import { T, lang } from '../i18n/i18n.mjs';
export const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const safeUrl = u => (/^https:\/\//i.test(String(u || '')) ? String(u) : '#');
export const STATUS_FR = { observed: 'Observé', 'potential-risk': 'Risque potentiel', hypothesis: 'Hypothèse', simulated: 'Simulé' };
const STATUS_EN = { observed: 'Observed', 'potential-risk': 'Potential risk', hypothesis: 'Hypothesis', simulated: 'Simulated' };
export const statusLabel = s => (lang() === 'fr' ? STATUS_FR : STATUS_EN)[s] || s;
const HELP = { observed: ['a measured fact, recorded in a public source', 'un fait mesuré, enregistré dans une source publique'], 'potential-risk': ['a signal worth checking, not an established fact', 'un signal qui mérite vérification, pas un fait établi'], hypothesis: ['an idea to test, without sufficient evidence', 'une idée à tester, sans preuve suffisante'], simulated: ['a model result, not an observation', 'un résultat de modèle, pas une observation'] };
export const STATUS_HELP = Object.fromEntries(Object.entries(HELP).map(([k, v]) => [k, v[1]]));
const DICT = {
  'Question ouverte sans preuve disponible': 'Open question without available evidence', 'Chevauchement de chantiers entre organisations': 'Overlapping works between organisations',
  'Trottoir plus étroit que le minimum du Better Streets Plan': 'Sidewalk narrower than the Better Streets Plan minimum', 'Travaux répétés au même endroit': 'Repeated works at the same place',
  'Permis débutant pendant un moratoire de chaussée': 'Permit starting during a street moratorium', 'Plantation à reporter à cause de travaux planifiés (simulation)': 'Planting to postpone because of planned works (simulation)',
  'Fenêtres de permis pendant une fermeture SFMTA': 'Permit windows during an SFMTA closure', 'Opportunité de coordination à venir': 'Upcoming coordination opportunity',
  'Demande d’un agent dans une mission enregistrée ; aucune source CORE ne permet d’y répondre.': 'Requested by an agent in a recorded mission; no CORE source can answer it.',
  'Des dérogations peuvent exister ; ce n’est pas une infraction démontrée.': 'Exemptions may exist; this is not a demonstrated violation.',
  'Détection déterministe sur des fenêtres administratives ; ce n’est ni un incident constaté ni une infraction.': 'Deterministic detection on administrative windows; neither an observed incident nor a violation.',
  'Mesure de 2014 ; la largeur actuelle peut différer. Le minimum BSP est une règle de conception, pas une norme d’accessibilité.': '2014 measurement; the current width may differ. The BSP minimum is a design rule, not an accessibility standard.',
  'Résultat d’un modèle exploratoire ; aucun emplacement réel n’a été vérifié.': 'Output of an exploratory model; no real site has been checked.',
  faible: 'low', moyenne: 'medium', 'élevée': 'high', 'non évaluée': 'not assessed', 'règle déclarée par CORE (non validée)': 'rule declared by CORE (not validated)', 'aucune méthode de sévérité définie pour ce type': 'no severity method defined for this type',
  'aucune : question ouverte': 'none: open question', 'élevée pour le fait enregistré ; actualité non vérifiée': 'high for the recorded fact; currency not verified', 'moyenne : motif administratif, impact non mesuré': 'medium: administrative pattern, impact not measured', 'faible : modèle non calibré': 'low: uncalibrated model',
  'aucune décision humaine enregistrée': 'no human decision recorded', 'aucun outil CORE ne peut y répondre': 'no CORE tool can answer it', 'analysé — preuves supplémentaires requises': 'analysed — more evidence required', 'analysé — revue humaine requise': 'analysed — human review required',
  'ÉLIGIBLE À LA REVUE HUMAINE': 'ELIGIBLE FOR HUMAN REVIEW', 'PREUVES SUPPLÉMENTAIRES REQUISES': 'MORE EVIDENCE REQUIRED', 'proposition (non vérifiée)': 'proposal (not verified)',
  'Scénarios de coordination S1–S4 calculés par le laboratoire déterministe (non validés sur le terrain)': 'Coordination scenarios S1–S4 computed by the deterministic lab (not validated on site)',
  'Alternative A3 de la simulation : planter après les travaux (simulé, non calibré)': 'Simulation alternative A3: plant after the works (simulated, uncalibrated)', 'Regroupement des fenêtres de travaux (scénarios S1–S4, non validés)': 'Grouping of works windows (scenarios S1–S4, not validated)',
  // Open questions raised by agents in recorded missions.
  'Confirmation de la compatibilité des excavations avec les normes d’accessibilité (E12, E14).': 'Confirmation that the excavations are compatible with accessibility standards (E12, E14).',
  'Données géocodées des adresses sur HOWARD ST pour un rattachement précis.': 'Geocoded addresses on HOWARD ST for precise matching.', 'Données géocodées pour les adresses sur HOWARD ST (E8).': 'Geocoded data for the addresses on HOWARD ST (E8).',
  'Données sur les dates exactes des travaux planifiés pour les 39 emplacements (E1).': 'Data on the exact dates of planned works for the 39 sites (E1).', 'Données sur les espacements et parts de linéaire utilisable réels (E3).': 'Data on actual spacing and usable frontage shares (E3).',
  'Données sur les impacts énergétiques des excavations sur le tronçon.': 'Data on the energy impacts of the excavations on the segment.', 'Données sur les permis de construction récents (E9) et leur lien avec les excavations (E4).': 'Data on recent building permits (E9) and their link with the excavations (E4).',
  'Données sur les permis de construction récents pour le tronçon (E9).': 'Data on recent building permits for the segment (E9).', 'Données sur les permis de construction récents pour le tronçon HOWARD ST 08TH ST → 09TH ST (E8).': 'Data on recent building permits for the segment HOWARD ST 08TH ST → 09TH ST (E8).',
  'Données sur les travaux planifiés pour les 39 emplacements à reporter (E1).': 'Data on planned works for the 39 sites to postpone (E1).', 'Preuve de la profondeur ou de l’étendue de l’excavation 26EXC-05114.': 'Evidence of the depth or extent of excavation 26EXC-05114.',
  'Preuve de la relation entre les 7 permis récents (E9) et le tronçon HOWARD ST 08TH ST → 09TH ST (E1).': 'Evidence of the relation between the 7 recent permits (E9) and the segment HOWARD ST 08TH ST → 09TH ST (E1).',
  'Preuve de la relation entre l’excavation 26EXC-05114 et les arbres proches.': 'Evidence of the relation between excavation 26EXC-05114 and nearby trees.', 'Preuve de la relation entre l’excavation 26EXC-05114 et les arbres situés à proximité.': 'Evidence of the relation between excavation 26EXC-05114 and trees located nearby.',
  'Preuve de la relation entre l’excavation 26EXC-05114 et les arbres à proximité.': 'Evidence of the relation between excavation 26EXC-05114 and nearby trees.', 'Preuve de la relation entre l’excavation 26EXC-05114 et les arbres à ≤ 12 m.': 'Evidence of the relation between excavation 26EXC-05114 and trees within 12 m.',
  'Preuve de l’impact de l’excavation 26EXC-05114 sur le tronçon HOWARD ST 08TH ST → 09TH ST.': 'Evidence of the impact of excavation 26EXC-05114 on the segment HOWARD ST 08TH ST → 09TH ST.', 'Preuve de l’impact environnemental de l’excavation 26EXC-05114 sur le tronçon HOWARD ST 08TH ST → 09TH ST.': 'Evidence of the environmental impact of excavation 26EXC-05114 on the segment HOWARD ST 08TH ST → 09TH ST.',
  'Preuve de l’impact spécifique de l’excavation 26EXC-05114 sur le tronçon HOWARD ST 08TH ST → 09TH ST.': 'Evidence of the specific impact of excavation 26EXC-05114 on the segment HOWARD ST 08TH ST → 09TH ST.', 'Quel est l’impact de l’excavation 26EXC-05114 sur le tronçon HOWARD ST 08TH ST → 09TH ST ?': 'What is the impact of excavation 26EXC-05114 on the segment HOWARD ST 08TH ST → 09TH ST?',
};
const TEMPLATES = [
  [/^Largeur mesurée (\d+(?:[.,]\d+)?) ft \(étude 2014\) < minimum (\d+(?:[.,]\d+)?) ft pour la classe « (.+) »\.$/, (w, mn, c) => `Measured width ${w} ft (2014 survey) < minimum ${mn} ft for the “${c}” class.`],
  [/^(\d+) permis concernés(?:, (\d+) organisations)?(?:, (\d+) jour\(s\) de chevauchement cumulé)?\.$/, (n, o, d) => `${n} permit(s) involved${o ? `, ${o} organisations` : ''}${d ? `, ${d} day(s) of cumulative overlap` : ''}.`],
  [/^(\d+) emplacement\(s\) simulé\(s\) à reporter \(modèle (.+), non calibré, empreinte (\w+)\)\.$/, (n, mo, f) => `${n} simulated site(s) to postpone (model ${mo}, uncalibrated, fingerprint ${f}).`],
  [/^(\d+) jour\(s\) de chevauchement cumulé \(≥ 60 élevée, ≥ 14 moyenne\)$/, d => `${d} day(s) of cumulative overlap (≥ 60 high, ≥ 14 medium)`],
  [/^(\d+) emplacement\(s\) simulé\(s\) \(≥ 5 moyenne\) — simulation non calibrée$/, n => `${n} simulated site(s) (≥ 5 medium) — uncalibrated simulation`],
  [/^écart au minimum BSP : (\d+(?:[.,]\d+)?) ft \(≥ 3 ft élevée, ≥ 1 ft moyenne\)$/, d => `gap to the BSP minimum: ${d} ft (≥ 3 ft high, ≥ 1 ft medium)`],
];
// French registry text → selected language.
export function ptext(s, code = lang()) {
  if (s == null || code === 'fr') return s ?? '';
  if (DICT[s]) return DICT[s];
  for (const [re, f] of TEMPLATES) { const m = re.exec(s); if (m) return f(...m.slice(1)); }
  return /[a-z]/i.test(s) && /[éèàùç’«]|\b(le|la|les|des|du|une|pour|avec|sur|aucun)\b/i.test(s) ? `${s} (original in French)` : s;
}
const SUFFIX = /^(ST|AVE|AV|BLVD|WAY|PL|LN|RD|DR|TER|AL|ALY|CT|SQ|HWY|PLZ)$/;
const word = w => /^0*\d+(ST|ND|RD|TH)$/.test(w) ? w.replace(/^0+/, '').toLowerCase() : SUFFIX.test(w) ? w[0] + w.slice(1).toLowerCase() : w[0] + w.slice(1).toLowerCase();
// "FOLSOM ST 05TH ST → FALMOUTH ST" → "Folsom St, between 5th St and Falmouth St"
export function humanPlace(place = '', code = lang()) {
  const [left, right] = String(place).split('→').map(s => s.trim().split(/\s+/).filter(Boolean));
  if (!left?.length) return String(place);
  const cut = left.findIndex(w => SUFFIX.test(w)), street = left.slice(0, cut + 1 || left.length), from = cut >= 0 ? left.slice(cut + 1) : [];
  const fmt = ws => ws.map(word).join(' ');
  return from.length && right?.length ? (code === 'fr' ? `${fmt(street)}, entre ${fmt(from)} et ${fmt(right)}` : `${fmt(street)}, between ${fmt(from)} and ${fmt(right)}`) : fmt(street) + (right?.length ? ` → ${fmt(right)}` : '');
}
const m = ft => `${(ft * 0.3048).toFixed(2).replace('.', lang() === 'fr' ? ',' : '.')} m`;
export function reviewSteps(p) {
  const inv = p.investigation || {};
  return [
    [T('Recorded from a public source', 'Enregistré depuis une source publique'), true, p.asOf ? T(`snapshot of ${p.asOf.slice(0, 10)}`, `instantané du ${p.asOf.slice(0, 10)}`) : ''],
    [T('Analysed by CORE agents', 'Analysé par les agents CORE'), !!inv.task, inv.label ? ptext(inv.label) : T('no analysis recorded', 'aucune analyse enregistrée')],
    [T('Human review', 'Revue humaine'), false, inv.state === 'awaiting-human' ? T('waiting — no verified human reviewer exists yet', 'en attente — aucun relecteur humain vérifié n’existe encore') : T('not started', 'non commencée')],
    [T('Decision', 'Décision'), false, ptext(p.humanDecision || 'aucune décision humaine enregistrée')],
  ];
}

export function problemHTML(p, { sidewalk = null, journey = null, count = 1 } = {}) {
  const st = p.status, steps = reviewSteps(p), mt = p.metrics || {};
  const measure = mt.width_ft != null && mt.min_ft != null ? `<div class="le-evidence">
      <span class="le-eyebrow">${T('What was measured', 'Ce qui a été mesuré')}</span>
      <div class="le-row" style="justify-content:space-between;align-items:baseline"><span class="v">${esc(mt.width_ft)} ft <small class="fine">(${m(mt.width_ft)})</small></span><span class="fine">minimum ${esc(mt.min_ft)} ft (${m(mt.min_ft)})${sidewalk?.recommended_ft ? ` · ${T('recommended', 'recommandé')} ${esc(sidewalk.recommended_ft)} ft` : ''}</span></div>
      <div class="le-meter" role="img" aria-label="${T(`Measured width ${esc(mt.width_ft)} feet against a minimum of ${esc(mt.min_ft)} feet`, `Largeur mesurée ${esc(mt.width_ft)} pieds sur un minimum de ${esc(mt.min_ft)} pieds`)}"><i style="width:${Math.min(100, (mt.width_ft / Math.max(mt.min_ft, sidewalk?.recommended_ft || mt.min_ft)) * 100).toFixed(1)}%"></i><u style="left:${((mt.min_ft / Math.max(mt.min_ft, sidewalk?.recommended_ft || mt.min_ft)) * 100).toFixed(1)}%" data-l="min."></u></div>
      <p class="src" style="margin-top:14px">${p.evidence.map(e => `<a href="${esc(safeUrl(e.url))}" target="_blank" rel="noopener noreferrer">${icon('external', 13)} DataSF · ${esc(e.ref)}</a>`).join(' · ')} — ${T('San Francisco sidewalk survey (2014)', 'étude des trottoirs de San Francisco (2014)')}</p></div>` : `<div class="le-evidence"><span class="le-eyebrow">${T('Evidence', 'Preuves')}</span><p>${esc(ptext(p.statement))}</p><p class="src">${p.evidence.map(e => `<a href="${esc(safeUrl(e.url))}" target="_blank" rel="noopener noreferrer">${esc(e.ref)}</a>`).join(' · ')}</p></div>`;
  return `<header class="pp-head">
    <div class="le-row"><span class="le-badge" data-s="${esc(st)}">${esc(statusLabel(st))}</span><span class="fine">${esc(T(...(HELP[st] || ['', ''])))}</span></div>
    <h2 id="pp-title">${esc(ptext(p.title))}</h2>
    <p class="pp-place">${icon('map', 15)} ${esc(humanPlace(p.place))}${count > 1 ? ` · <span class="fine">${T(`${count} problems recorded on this segment`, `${count} problèmes enregistrés sur ce tronçon`)}</span>` : ''}</p></header>
  <p class="pp-lede">${esc(ptext(p.statement))}</p>
  ${measure}
  <div class="pp-unc"><b>${icon('info', 15)} ${T('What we do not know', 'Ce que l’on ne sait pas')}</b><p>${esc(p.caveat ? ptext(p.caveat) : T('No limitation declared in the record: to be checked.', 'Aucune limite déclarée dans l’enregistrement : à vérifier.'))}</p>${p.confidence ? `<p class="fine">${T('Confidence', 'Confiance')} : ${esc(ptext(p.confidence))}</p>` : ''}</div>
  <div class="pp-sec"><h3>${T('Where the review stands', 'Où en est l’examen')}</h3><ol class="le-steps">${steps.map(([l, ok, d], i) => `<li class="${ok ? 'done' : i === steps.findIndex(s => !s[1]) ? 'now' : ''}"><div><b>${esc(l)}</b><br><span class="fine">${esc(d)}</span></div></li>`).join('')}</ol></div>
  <div class="pp-sec"><h3>${T('Ideas and contributions', 'Idées et contributions')}</h3>${journey?.idea ? `<p>${T(`You have a private idea linked to this problem (${journey.idea.versions || 0} version(s)), encrypted in your vault.`, `Vous avez une idée privée liée à ce problème (${journey.idea.versions || 0} version(s)), chiffrée dans votre coffre.`)}</p>` : `<p class="fine">${T('No idea from you yet. Ideas stay private and encrypted in this browser; nobody else’s contribution is published in this prototype.', 'Aucune idée de votre part pour l’instant. Les idées restent privées et chiffrées dans ce navigateur ; aucune contribution d’autrui n’est publiée dans ce prototype.')}</p>`}</div>
  <nav class="pp-actions" aria-label="${T('Participate', 'Participer')}">
    <a class="btn" href="dialogue.html#problem=${encodeURIComponent(p.id)}&mode=understand">${icon('book', 16)} ${T('Understand', 'Comprendre')}</a>
    <a class="btn primary" href="dialogue.html#problem=${encodeURIComponent(p.id)}&mode=propose">${icon('bulb', 16)} ${T('Propose', 'Proposer')}</a>
    <a class="btn" href="commons.html#communities?problem=${encodeURIComponent(p.id)}">${icon('collaborate', 16)} ${T('Collaborate', 'Collaborer')}</a></nav>
  <details class="pp-adv"><summary>${T('Technical details', 'Détails techniques')}</summary><dl class="kv">
    <dt>${T('Identifier', 'Identifiant')}</dt><dd><code>${esc(p.id)}</code></dd><dt>${T('Segment (CNN)', 'Tronçon (CNN)')}</dt><dd><code>${esc(p.segment || '—')}</code></dd><dt>${T('Domain', 'Domaine')}</dt><dd>${esc(p.domain)}</dd>
    <dt>${T('Severity', 'Gravité')}</dt><dd>${esc(ptext(p.severity?.level || '—'))} — ${esc(ptext(p.severity?.basis || ''))} (${esc(ptext(p.severity?.method || ''))})</dd>
    <dt>${T('Investigation', 'Investigation')}</dt><dd>${esc(p.investigation?.task || '—')} · ${esc(ptext(p.investigation?.decision || '—'))}</dd>
    <dt>${T('Assigned agents', 'Agents assignés')}</dt><dd>${(p.assignedAgents || []).length}</dd><dt>${T('Verified on', 'Vérifié le')}</dt><dd>${esc((p.lastVerified || '').slice(0, 10))}</dd></dl></details>`;
}
